import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/getting-started.md","filePath":"zh/kimi-code-cli/guides/getting-started.md"}`),a={name:`kimi-code-cli/guides/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”">​</a></h1><h2 id="kimi-code-cli-是什么" tabindex="-1">Kimi Code CLI 是什么 <a class="header-anchor" href="#kimi-code-cli-是什么" aria-label="Permalink to “Kimi Code CLI 是什么”">​</a></h2><p>Kimi Code CLI 是一个运行在终端中的 AI Agent，帮助你完成软件开发任务和日常的终端操作——阅读和修改代码、执行 Shell 命令、搜索文件、抓取网页，并在执行过程中根据反馈自主规划和调整下一步行动。</p><p>它适用于以下场景：</p><ul><li><strong>编写和修改代码</strong>：实现新功能、修复 bug、完成重构</li><li><strong>理解项目</strong>：探索陌生的代码库，解答架构和实现层面的问题</li><li><strong>自动化任务</strong>：批量处理文件、运行构建与测试、串联多个脚本</li></ul><p>整套 CLI 以 TypeScript 编写，通过 npm 分发，运行在 Node.js 之上。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><p>提供两种安装方式：官方安装脚本（推荐，无需预装 Node.js）和 npm 全局安装。</p><div class="tip custom-block"><p class="custom-block-title">安装之前</p><p>Kimi Code CLI 为全交互式 TUI 应用，推荐在支持真彩色与连字的现代终端中运行以获得最佳体验，例如 <a href="https://sw.kovidgoyal.net/kitty/" target="_blank" rel="noreferrer">Kitty</a> 或 <a href="https://ghostty.org/" target="_blank" rel="noreferrer">Ghostty</a>。</p></div><h3 id="脚本安装-推荐" tabindex="-1">脚本安装（推荐） <a class="header-anchor" href="#脚本安装-推荐" aria-label="Permalink to “脚本安装（推荐）”">​</a></h3><ul><li><strong>macOS / Linux</strong>：</li></ul><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://code.kimi.com/kimi-code/install.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><ul><li><strong>Windows（PowerShell）</strong>：</li></ul><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">code.kimi.com</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kimi</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><blockquote><p>Windows 用户首次启动前还需要安装 <a href="https://gitforwindows.org/" target="_blank" rel="noreferrer">Git for Windows</a>，Kimi Code CLI 会使用其中的 Git Bash 作为 Shell 环境。如果 Git Bash 安装在非标准路径，请把 <code>KIMI_SHELL_PATH</code> 设为 <code>bash.exe</code> 的绝对路径。</p></blockquote><p>脚本会自动下载最新版本、校验 checksum，并把 <code>kimi</code> 可执行文件放到你的 <code>PATH</code> 中。</p><h3 id="npm-安装" tabindex="-1">npm 安装 <a class="header-anchor" href="#npm-安装" aria-label="Permalink to “npm 安装”">​</a></h3><p>需要 Node.js 22.19.0 或更高版本：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><p>或用 pnpm：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><h2 id="升级与卸载" tabindex="-1">升级与卸载 <a class="header-anchor" href="#升级与卸载" aria-label="Permalink to “升级与卸载”">​</a></h2><p>安装完成后，验证可执行文件是否就绪：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p><strong>升级</strong>：运行 <code>kimi upgrade</code>，CLI 会检查最新版本并展示更新选项。选择 <code>Install update now</code> 后根据当前安装来源执行升级；也可以直接用包管理器：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code@latest</span></span></code></pre></div><p><strong>卸载</strong>：脚本安装的用户删除 <code>kimi</code> 可执行文件即可；npm 安装的用户：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><h2 id="第一次启动" tabindex="-1">第一次启动 <a class="header-anchor" href="#第一次启动" aria-label="Permalink to “第一次启动”">​</a></h2><p>进入项目目录后直接运行 <code>kimi</code> 启动交互界面：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>只想执行一条指令而不进入交互界面时，使用 <code>-p</code>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我看一下这个项目的目录结构&quot;</span></span></code></pre></div><p>继续上一次会话加 <code>-c</code>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre></div><p>首次启动时需要配置 API 来源。在交互界面中输入 <code>/login</code> 进入登录流程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/login</span></span></code></pre></div><p><code>/login</code> 会弹出平台选择器，支持两种方式：</p><ul><li><strong>Kimi Code（OAuth）</strong> — 验证码流程，在任意设备打开链接、登录并输入验证码即可授权</li><li><strong>Kimi Platform API 密钥</strong> — 输入来自 <code>platform.kimi.com</code> 或 <code>platform.kimi.ai</code> 的 API 密钥</li></ul><p>需要退出登录时，输入 <code>/logout</code> 清除当前凭证。</p><div class="tip custom-block"><p class="custom-block-title">使用其他 AI 供应商</p><p>如果你想接入 Anthropic、OpenAI、Google 等其他供应商，需要直接编辑 <code>~/.kimi-code/config.toml</code> 配置 API 密钥，详见<a href="/code/docs/kimi-code-cli/configuration/providers.html">平台与模型</a>。配置项完整说明见<a href="/code/docs/kimi-code-cli/configuration/config-files.html">配置文件</a>、<a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a>和<a href="/code/docs/kimi-code-cli/configuration/overrides.html">配置覆盖</a>。</p></div><h2 id="第一个对话" tabindex="-1">第一个对话 <a class="header-anchor" href="#第一个对话" aria-label="Permalink to “第一个对话”">​</a></h2><p>登录完成后，用自然语言描述任务即可。先让它熟悉当前项目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>帮我看一下这个项目的目录结构，简单介绍一下每个目录是做什么的</span></span></code></pre></div><p>Kimi Code CLI 会自动调用文件读取、搜索等工具浏览相关内容后给出回答。只读操作默认自动执行无需确认；对于会修改文件或执行 Shell 命令的操作，默认会在执行前征求确认。</p><p>也可以直接描述更具体的任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>在 src/utils 里新增一个函数，用来把任意字符串转成 kebab-case，并补一个单元测试</span></span></code></pre></div><p>Kimi Code CLI 会规划步骤、修改代码、运行测试，并在每一步告诉你它做了什么。</p><div class="tip custom-block"><p class="custom-block-title">不知道能做什么？输入 <code>/help</code></p><p>随时在输入框输入 <code>/help</code>，可以打开内置的命令和快捷键面板，按 <code>↑</code>/<code>↓</code> 翻看，<code>Esc</code> 关闭。退出时输入 <code>/exit</code>，或按 <code>Ctrl-C</code> 两次，或在输入框为空时按 <code>Ctrl-D</code>。</p></div><h2 id="常用命令与快捷键速查" tabindex="-1">常用命令与快捷键速查 <a class="header-anchor" href="#常用命令与快捷键速查" aria-label="Permalink to “常用命令与快捷键速查”">​</a></h2><p>第一次使用时，记住下面这些就够了：</p><p><strong>会话相关命令</strong></p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/new</code></td><td>开启新会话，清空当前上下文</td></tr><tr><td><code>/sessions</code></td><td>浏览历史会话，选择恢复</td></tr><tr><td><code>/model</code></td><td>切换当前使用的模型</td></tr><tr><td><code>/compact</code></td><td>手动压缩上下文，释放 token</td></tr><tr><td><code>/fork</code></td><td>派生当前会话，保留历史独立继续</td></tr></tbody></table><p><strong>最常用快捷键</strong></p><table tabindex="0"><thead><tr><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>中断流式输出 / 关闭弹窗</td></tr><tr><td><code>Ctrl-C</code></td><td>中断输出；空闲时连按两次退出</td></tr><tr><td><code>Shift-Tab</code></td><td>切换 Plan 模式</td></tr><tr><td><code>Ctrl-S</code></td><td>输出中途插入消息，无需等待结束</td></tr><tr><td><code>Ctrl-O</code></td><td>折叠 / 展开工具输出和压缩摘要</td></tr></tbody></table><p>想看完整列表，输入 <code>/help</code> 或访问<a href="/code/docs/kimi-code-cli/reference/slash-commands.html">斜杠命令参考</a>和<a href="/code/docs/kimi-code-cli/reference/keyboard.html">键盘快捷键</a>。</p><h2 id="数据存放在哪里" tabindex="-1">数据存放在哪里 <a class="header-anchor" href="#数据存放在哪里" aria-label="Permalink to “数据存放在哪里”">​</a></h2><p>Kimi Code CLI 的本地数据默认保存在 <code>~/.kimi-code/</code> 下，包含配置文件、会话记录、日志和更新缓存。如需迁移到别处，通过 <code>KIMI_CODE_HOME</code> 环境变量指定新路径。完整说明见<a href="/code/docs/kimi-code-cli/configuration/data-locations.html">数据路径</a>和<a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/guides/interaction.html">交互与输入</a> — 输入框操作、审批流程、Plan 模式和 YOLO 模式详解</li><li><a href="/code/docs/kimi-code-cli/guides/sessions.html">会话与上下文</a> — 恢复会话、上下文压缩、导出会话</li><li><a href="/code/docs/kimi-code-cli/guides/use-cases.html">常见使用案例</a> — 典型任务的 prompt 示例</li></ul>`,60)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};